solution.code:
#include <stdio.h>

int main() {
    int values[] = {7, 8, 8};
    int n = 3;
    int sum = 0;
    for (int i = 0; i < n; i++) {
        sum += values[i];
    }
    double average = (double)sum / n;
    printf("Average: %.2f\n", average);
    return 0;
}
